SELECT TASK_ID, NAME_KEY, FILE_SHA256, FILE_SIZE, FILE_MTIME_MS, INSTITUTION_ID, STATE_CD, REASON_CD,
       HAS_IMAGES, HAS_EMBEDDED, ORDER_APPROX, HIT_ROWS, CHECKER_VER, CHECKED_AT
  FROM DOC_CHECK WHERE TASK_ID = #{taskId}

SELECT TASK_ID, NAME_KEY, FOUND_INST_ID, LOC_KIND, LOC_NO, HIT_COUNT
  FROM DOC_CHECK_HIT WHERE TASK_ID = #{taskId}
 AND NAME_KEY = #{nameKey}
